89	// SG_TUNED_UNROLL-parameterized scalar apply; calls canonical looksam_apply_step.
90	template <typename ParamT, typename GradT, int UNROLL>
91	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_LOOKSAM_MIN_BLOCKS)
92	looksam_apply_kernel(
93	    ParamT* param, float* exp_avg, float* exp_avg_sq,
94	    const float* sam_dir, const GradT* grad,
95	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
96	    float bc1, float bc2, int64_t N
97	) {
98	    const int64_t stride = prim::grid_stride() * UNROLL;
99	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
100	    for (int64_t base = base0; base < N; base += stride) {
101	        #pragma unroll
102	        for (int u = 0; u < UNROLL; ++u) {
103	            const int64_t i = base + u;
104	            if (i < N) {
105	                SG_SANITIZE_GRAD_INPLACE(grad, i);
106	                looksam_apply_step(param, exp_avg, exp_avg_sq, sam_dir, grad,
107	                                   alpha, lr, beta1, beta2, eps, wd,
108	                                   bc1, bc2, i);
109	            }
110	        }
111	    }
112	}
