114	// FP32 vec4 fast path for the Adam apply: float4 traffic, canonical step 4×.
115	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_LOOKSAM_MIN_BLOCKS)
116	looksam_apply_kernel_vec4_fp32(
117	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
118	    const float4* sam_dir4, const float4* grad4,
119	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
120	    float bc1, float bc2, int64_t N4
121	) {
122	    const int64_t stride = prim::grid_stride();
123	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
124	        SG_SANITIZE_GRAD4_INPLACE(grad4, i);
125	        float4 p  = prim::ld_f32v4(param4 + i);
126	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
127	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
128	        float4 d  = prim::ldg_f32v4(sam_dir4 + i);
129	        float4 g  = prim::ldg_f32v4(grad4 + i);
130	        #pragma unroll
131	        for (int u = 0; u < 4; ++u) {
132	            looksam_apply_step(&p.x, &m.x, &v.x, &d.x, &g.x,
133	                               alpha, lr, beta1, beta2, eps, wd, bc1, bc2, u);
134	        }
135	        prim::st_f32v4(param4 + i, p);
136	        prim::st_f32v4(exp_avg4 + i, m);
137	        prim::st_f32v4(exp_avg_sq4 + i, v);
138	    }
139	}
