141	void launch_looksam_perturb(
142	    torch::Tensor param, torch::Tensor backup,
143	    torch::Tensor grad, float scale
144	) {
145	    const int64_t N = param.numel();
146	    if (N == 0) return;
147	    auto stream = at::cuda::getCurrentCUDAStream().stream();
148	    const int block = SG_TUNED_BLOCK_SIZE;
149	    // Clamp the grid in int64 (N can exceed 2^31) then cast the grid dim to int
150	    // (grid dims are int; the element index inside the kernel is int64_t).
151	    const int grid = static_cast<int>(
152	        std::min<int64_t>(65535, (N + block - 1) / block));
153	
154	    AT_DISPATCH_FLOATING_TYPES_AND2(
155	        at::ScalarType::Half, at::ScalarType::BFloat16,
156	        param.scalar_type(), "looksam_perturb", [&] {
157	            looksam_perturb_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
158	                param.data_ptr<scalar_t>(),
159	                backup.data_ptr<scalar_t>(),
160	                grad.data_ptr<scalar_t>(),
161	                scale, N);
162	            SG_LAUNCH_CHECK(stream);
163	        });
