213	void launch_looksam_apply(
214	    torch::Tensor& param,
215	    torch::Tensor& exp_avg,
216	    torch::Tensor& exp_avg_sq,
217	    const torch::Tensor& sam_dir,
218	    const torch::Tensor& grad,
219	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
220	    float bc1, float bc2
221	) {
222	    const int64_t N = param.numel();
223	    if (N == 0) return;
224	    auto stream = at::cuda::getCurrentCUDAStream().stream();
225	
226	    // §6.1: keep the Adam moments (m, v) L2-resident across the SAM apply.
227	    prim::L2PersistScope l2(stream,
228	        exp_avg.data_ptr(), exp_avg.nbytes(),
229	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
230	
231	    const int block = SG_TUNED_BLOCK_SIZE;
232	    // Clamp the grid in int64 (N can exceed 2^31) then cast the grid dim to int
233	    // (grid dims are int; the element index inside the kernel is int64_t).
234	    const int grid = static_cast<int>(
235	        std::min<int64_t>(65535, (N + block - 1) / block));
236	
237	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
238	                          grad.scalar_type() == torch::kFloat32;
239	
240	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
241	        prim::is_vec4_alignable(param.data_ptr(), N) &&
242	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
243	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
244	        prim::is_vec4_alignable(sam_dir.data_ptr(), N) &&
245	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
246	        const int64_t N4 = N / 4;
247	        const int grid4 = static_cast<int>(
248	            std::min<int64_t>(65535, (N4 + block - 1) / block));
249	        looksam_apply_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
250	            reinterpret_cast<float4*>(param.data_ptr<float>()),
251	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
252	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
253	            reinterpret_cast<const float4*>(sam_dir.data_ptr<float>()),
254	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
255	            alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
256	        SG_LAUNCH_CHECK(stream);
257	        return;
258	    }
259	
260	    AT_DISPATCH_FLOATING_TYPES_AND2(
261	        at::ScalarType::Half, at::ScalarType::BFloat16,
262	        param.scalar_type(), "looksam_apply", [&] {
263	            looksam_apply_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
264	                <<<grid, block, 0, stream>>>(
265	                param.data_ptr<scalar_t>(),
266	                exp_avg.data_ptr<float>(),
267	                exp_avg_sq.data_ptr<float>(),
268	                sam_dir.data_ptr<float>(),
269	                grad.data_ptr<scalar_t>(),
270	                alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N);
271	            SG_LAUNCH_CHECK(stream);
272	        });
273	}
