292	) {
293	    const int64_t N = grad.numel();
294	    if (N == 0) return;
295	    auto stream = at::cuda::getCurrentCUDAStream().stream();
296	    const int block = SG_TUNED_BLOCK_SIZE;
297	    // Clamp the grid in int64 (N can exceed 2^31) then cast the grid dim to int
298	    // (grid dims are int; the element index inside the kernel is int64_t).
299	    const int grid = static_cast<int>(
300	        std::min<int64_t>(65535, (N + block - 1) / block));
301	    looksam_direction_adjust_kernel<<<grid, block, 0, stream>>>(
302	        grad.data_ptr<float>(), v_dir.data_ptr<float>(),
303	        inv_norm, lambda, grad_norm, N);
304	    SG_LAUNCH_CHECK(stream);
