493	// Pre-refactor csrc/common/ops.cpp::looksam_perturb_all.
494	// Returns a vector of backups (param.clone() before perturb).
495	std::vector<torch::Tensor> looksam_perturb_all(
496	 std::vector<torch::Tensor>& params,
497	 std::vector<torch::Tensor>& grads,
498	 float rho
499	) {
500	 float grad_norm = compute_sam_grad_norm_device_side(grads, grads.size());
501	 float rho_over_norm = rho / grad_norm;
502	
503	 std::vector<torch::Tensor> backups;
504	 backups.reserve(params.size());
505	 for (size_t i = 0; i < params.size(); i++) {
506	 // Params without a grad are never perturbed below, so cloning them is
507	 // wasted work. Skip the clone and store the param itself as the backup:
508	 // since the param is left untouched, the later restore (copy backup→param)
509	 // is a value-preserving self-copy no-op — behavior is identical, minus the
510	 // clone/alloc. Backups stays index-aligned with params for restore.
511	 if (!grads[i].defined() || grads[i].numel() == 0) {
512	 backups.push_back(params[i]);
513	 continue;
514	 }
515	 backups.push_back(params[i].clone());
516	 SG_DISPATCH_CALL(launch_looksam_perturb,
517	 params[i], backups[i], grads[i], rho_over_norm);
518	 }
519	 return backups;
520	}
