532	// Pre-refactor csrc/common/ops.cpp::looksam_compute_directions_and_adjust.
533	// Batches the per-tensor norm reductions into 2 CPU syncs (diff + grad
534	// norms via torch::stack), then dispatches the fused adjust kernel.
535	void looksam_compute_directions_and_adjust(
536	 std::vector<torch::Tensor>& grads,
537	 std::vector<torch::Tensor>& sam_grads,
538	 std::vector<torch::Tensor>& normal_grads,
539	 float la
540	) {
541	 std::vector<size_t> valid_idx;
542	 for (size_t i = 0; i < grads.size(); i++) {
543	 if (!sam_grads[i].defined() || !normal_grads[i].defined()
544	 || sam_grads[i].numel() == 0) continue;
545	 valid_idx.push_back(i);
546	 }
547	 if (valid_idx.empty()) return;
548	
549	 std::vector<torch::Tensor> diff_norms_t, grad_norms_t, diffs;
550	 diff_norms_t.reserve(valid_idx.size());
551	 grad_norms_t.reserve(valid_idx.size());
552	 diffs.reserve(valid_idx.size());
553	 for (auto i : valid_idx) {
554	 auto diff = (sam_grads[i] - normal_grads[i]).to(torch::kFloat32);
555	 diffs.push_back(diff);
556	 diff_norms_t.push_back(diff.norm());
557	 grad_norms_t.push_back(grads[i].norm());
558	 }
559	 auto diff_norms = torch::stack(diff_norms_t).cpu();
560	 auto grad_norms = torch::stack(grad_norms_t).cpu();
561	 auto* dnp = diff_norms.data_ptr<float>();
562	 auto* gnp = grad_norms.data_ptr<float>();
563	
564	 for (size_t vi = 0; vi < valid_idx.size(); vi++) {
565	 size_t i = valid_idx[vi];
566	 float dn = dnp[vi];
567	 if (dn < 1e-12f) continue;
568	 float inv_norm = 1.0f / dn;
